async function runDiff(older, newer) {
  const stdout = await runPython(
    ["-m", "vi3ion.cli", "diff", older, newer, "--json"],
    240000,
    vi3ionEnv(),
  );
  if (!stdout) return null;
  try {
    return JSON.parse(stdout);
  } catch {
    return null;
  }
}

function formatDiff(diff, olderName, newerName) {
  const parts = [];
  parts.push(`<context key="vi3ion-diff" title="Version comparison: ${olderName} -> ${newerName}">`);
  if (!diff || !diff.data || !diff.data.diff) {
    parts.push("Vi3ion could not compare these images. Do not guess what changed.");
    parts.push("</context>");
    return parts.join("\n");
  }
  const d = diff.data.diff;
  parts.push(
    `${diff.summary || `${d.change_count} change(s)`} ` +
      `(layout ${Math.round(d.layout_similarity * 100)}%, text ${Math.round(d.text_similarity * 100)}%)`,
  );
  const changes = (d.changes || []).slice(0, 15);
  if (!changes.length) {
    parts.push("No text or layout changes were observed between the two versions.");
  } else {
    parts.push(`Observed changes (${d.change_count}):`);
    for (const c of changes) {
      const region = c.region || "?";
      if (c.kind === "added") parts.push(`- added [${region}]: "${c.new}"`);
      else if (c.kind === "removed") parts.push(`- removed [${region}]: "${c.old}"`);
      else parts.push(`- ${c.kind} [${region}]: "${c.old}" -> "${c.new}"`);
    }
    if (d.change_count > changes.length) {
      parts.push(`… ${d.change_count - changes.length} more change(s) not shown.`);
    }
  }
  // Pixel comparison catches changes that carry no text (colour, spacing).
  const visual = diff.data.visual;
  if (visual && visual.available) {
    parts.push(
      `Pixel comparison: ${visual.changed_percent}% of pixels differ` +
        (visual.changed_region_count
          ? ` in ${visual.changed_region_count} area(s)` +
            ` (${visual.changed_regions.slice(0, 4).map((r) => `${r.position} @${r.bbox.join(",")}`).join("; ")})`
          : "") +
        ".",
    );
    if (!changes.length && visual.changed_percent > 0.05) {
      parts.push(
        "The pixels changed but no text changed: look for a colour, size or position change " +
          "in the listed areas, and ask the user to confirm.",
      );
    }
  }
  parts.push(
    "These are observed OCR/layout differences, not confirmed product changes. " +
      "Confirm identity (same screen?) and verify each change against the code or commit diff before reporting.",
  );
  parts.push("</context>");
  return parts.join("\n");
}

// Analyse the images of the newest user message and build the evidence text.
//
// The attachment arrives on the message (mime + bytes), so this is the only
// place where clipboard images and file attachments can both be resolved.
// Returns null when there is nothing new to analyse.
// --- Update awareness ------------------------------------------------------
// Reports only. Never installs on its own; every upgrade goes through the
// OpenCode permission prompt first (see the vi3ion_update tool). Auto-update
// consent just makes that prompt opt into "always allow" after the first time.
let updatesPending = null; // { engine: bool, plugin: bool } | null

function updateBlockText(pending) {
  if (!pending) return "";
  const bits = [];
  if (pending.engine) bits.push("engine update: pip install -U vi3ion");
  if (pending.plugin)
    bits.push("plugin update: npm i -D @subadeepan_y/vi3ion-opencode@latest");
  if (!bits.length) return "";
  return (
    "VI3ION update available — " +
    bits.join("; ") +
    ". If the user asks to update, call the vi3ion_update tool."
  );
}

async function maybeRunEngineUpgrade(ctx, perms) {
  const python = pythonPath();
  if (!python) {
    return "Cannot update: no Python with Vi3ion found (set VI3ION_PYTHON).";
  }
  try {
    await ctx.permission.assert({
      sessionID: perms && perms.sessionID,
      agent: perms && perms.agent,
      source:
        perms && perms.messageID
          ? { type: "tool", messageID: perms.messageID, id: perms.id || "vi3ion_update" }
          : { type: "tool", id: "vi3ion_update" },
      action: "vi3ion.update",
      resources: ["engine"],
      save: perms && perms.auto ? ["vi3ion.update"] : [],
    });
  } catch (error) {
    return `Update declined: ${error && error.message ? error.message : "permission denied"}`;
  }
  return new Promise((resolve) => {
    execFile(
      python,
      ["-m", "pip", "install", "-U", "vi3ion"],
      { timeout: 300000, windowsHide: true, env: vi3ionEnv() },
      (err, stdout, stderr) => {
        if (err) {
          resolve(
            `Upgrade failed: ${err.message} — ${String(stderr || "").slice(-300)}`,
          );
        } else {
          resolve("Engine upgraded to the latest vi3ion.");
        }
      },
    );
  });
}

async function setupUpdateMonitor(ctx, options) {
  try {
    const result = await checkUpdates(ctx, { python: pythonPath() });
    if (!result) return;
    const engine = !!(result.engine && result.engine.update_available);
    const plugin = !!(result.plugin && result.plugin.update_available);
    if (!engine && !plugin) return;
    updatesPending = { engine, plugin };
    // Auto-update consent: upgrade the engine at startup, still gated by the
    // permission prompt (the user sees the first one and can pick "always").
    if (engine) {
      const auto = await readAutoFlag(ctx).catch(() => false);
      if (auto) {
        const text = await maybeRunEngineUpgrade(ctx, { auto: true });
        if (!text.startsWith("Engine upgraded")) {
          console.error(`[vi3ion-attach] auto-update: ${text}`);
        }
      }
    }
  } catch (error) {
    console.error(`[vi3ion-attach] update monitor failed: ${error.message}`);
  }
}

